import{c as t,Q as a,j as o,m as s}from"./chunks/framework.BXc4yaFE.js";const p=JSON.parse('{"title":"10 Open-Source Repos That Quietly Make Claude Code 10x Better (Full Guide)","description":"","frontmatter":{"url":"https://x.com/undefinedKi/status/2070852381164630023","title":"10 Open-Source Repos That Quietly Make Claude Code 10x Better (Full Guide)","author":"undefinedKi","archived":"2026-06-28T00:00:00.000Z","handle":"@undefinedKi","published":"2026-06-27T00:00:00.000Z","stats":"161 likes · 19 retweets · 528 bookmarks · 187989 views","tags":["claude-code","open-source","skills","repos","ecosystem","memory","security"],"type":"twitter-article"},"headers":[],"relativePath":"research/tweets/2026-06-27-@undefinedKi-630023.md","filePath":"research/tweets/2026-06-27-@undefinedKi-630023.md","lastUpdated":1785909234000}'),n={name:"research/tweets/2026-06-27-@undefinedKi-630023.md"};function i(r,e,l,d,h,u){return a(),o("div",null,[...e[0]||(e[0]=[s(`<h1 id="_10-open-source-repos-that-quietly-make-claude-code-10x-better-full-guide-—-undefinedki" tabindex="-1">10 Open-Source Repos That Quietly Make Claude Code 10x Better (Full Guide) — @undefinedKi <a class="header-anchor" href="#_10-open-source-repos-that-quietly-make-claude-code-10x-better-full-guide-—-undefinedki" aria-label="Permalink to &quot;10 Open-Source Repos That Quietly Make Claude Code 10x Better (Full Guide) — @undefinedKi&quot;">​</a></h1><p><strong>來源</strong>：<a href="https://x.com/undefinedKi/status/2070852381164630023" target="_blank" rel="noreferrer">https://x.com/undefinedKi/status/2070852381164630023</a><strong>作者</strong>：undefinedKi（@undefinedKi） <strong>發布日期</strong>：2026-06-27 <strong>收錄日期</strong>：2026-06-28 <strong>類型</strong>：Twitter Article <strong>統計</strong>：161 likes · 19 retweets · 528 bookmarks · 187989 views</p><hr><h2 id="全文" tabindex="-1">全文 <a class="header-anchor" href="#全文" aria-label="Permalink to &quot;全文&quot;">​</a></h2><p>Claude Code is already the most capable coding agent out there. It plans, writes, debugs, ships. But here&#39;s the thing almost nobody tells you: if you&#39;re running it raw, out of the box, you&#39;re using maybe 20% of what it can actually do. The other 80% lives in open-source repos. Skills, harnesses, memory layers, agent teams. Stuff built by people who use Claude Code every single day and got tired of its limits. Plugged in, these turn one agent into something that remembers your codebase, reviews its own work, and ships like a full team. But most of the repos getting hyped right now are noise. Inflated star counts, slick landing pages, and skills that just bloat your context and slow Claude down without doing anything useful. Install the wrong ones and you&#39;ve made your setup worse, not better. So I went through them. Checked the real GitHub numbers, read the docs, tested the setups, and noted who built each one and why it spread. What&#39;s left is 10 repos that are actually worth your time. For each one I&#39;ll cover what it is, who it&#39;s for, and exactly how to use it. Let&#39;s go.</p><h1 id="first-for-anyone-new-to-this-skip-if-you-know-github" tabindex="-1">First, for anyone new to this (skip if you know GitHub) <a class="header-anchor" href="#first-for-anyone-new-to-this-skip-if-you-know-github" aria-label="Permalink to &quot;First, for anyone new to this (skip if you know GitHub)&quot;">​</a></h1><p>GitHub is basically the world&#39;s biggest library of open-source code. People build tools and put them there for free, for anyone to download and use. A &quot;repo&quot; (repository) is just one project&#39;s folder, the code, the instructions, everything. &quot;Stars&quot; are like likes: the more stars, the more people found it useful. When I say a repo has 200k stars, that&#39;s a strong signal it&#39;s the real deal. Almost every repo here works the same way with Claude Code. The pattern:</p><ol><li>Open Claude Code, either in your terminal or in the Claude app (the Code tab).</li><li>Install it one of two ways. Either copy the one-line install command from the repo&#39;s README (its main page), or just paste the repo link into Claude Code and say &quot;install this repo for me.&quot; Claude will read the instructions and set it up itself.</li><li>That&#39;s it. The new skill or tool is now available. You call it with a slash command like /review, or just by asking Claude in plain English. No coding required for most of these. If you can copy and paste, you can run them. I&#39;ll give the exact command for each one below.</li></ol><h1 id="_1-ecc-everything-claude-code-—-affaan-m-ecc" tabindex="-1">1. ECC (Everything Claude Code) — affaan-m/ECC <a class="header-anchor" href="#_1-ecc-everything-claude-code-—-affaan-m-ecc" aria-label="Permalink to &quot;1. ECC (Everything Claude Code) — affaan-m/ECC&quot;">​</a></h1><p>~210,000+ stars Start here, because this is the one that started the whole &quot;configs as a product&quot; wave. If you&#39;ve used Claude Code, you&#39;ve seen it: it writes code that breaks, says it &quot;fixed&quot; something it didn&#39;t, forgets what you told it five minutes ago, and starts every new chat from zero. That&#39;s not you doing it wrong. That&#39;s what coding agents do without rules. ECC is the fix. A solo dev, Affaan Mustafa, won an Anthropic hackathon building a full product in 8 hours with just Claude Code, then open-sourced the exact setup he&#39;d spent 10 months refining. It hit 200,000+ stars, one of the most-starred AI repos on GitHub. Once installed, it sits in the background and forces Claude to actually behave: write tests before claiming success, stop faking passing checks, stop committing broken code, and remember your project between sessions. You install it once and every session after that is sharper, with way less hand-holding. Open Claude Code and run:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/plugin marketplace add https://github.com/affaan-m/ECC</span></span>
<span class="line"><span>/plugin install ecc@ecc</span></span></code></pre></div><p>After that you just work normally and most of it runs automatically. But here&#39;s where it gets useful day to day. A few commands you&#39;ll actually use:</p><blockquote><p>/ecc:plan &quot;add user login with Google&quot; maps out the whole feature before Claude writes a single line, so you don&#39;t get 200 lines of the wrong thing. npx ecc-agentshield scan checks your project for security holes, then npx ecc-agentshield scan --fix patches the safe ones automatically. /analyze-repo drops Claude into an unfamiliar codebase and gives you a clean map of how it all fits together, perfect when you inherit someone else&#39;s project. /instinct-status shows you what ECC has learned from your past sessions. The longer you use it, the more it adapts to how you build. The rest, like enforcing tests, saving context, and blocking broken commits, just happens once it&#39;s installed.</p></blockquote><h1 id="_2-gstack-—-garrytan-gstack" tabindex="-1">2. GStack — garrytan/gstack <a class="header-anchor" href="#_2-gstack-—-garrytan-gstack" aria-label="Permalink to &quot;2. GStack — garrytan/gstack&quot;">​</a></h1><p>115,000+ stars This one&#39;s from Garry Tan, the CEO of Y Combinator, the startup accelerator behind Coinbase, Airbnb, and Stripe. He&#39;s been building products for 20 years, and he open-sourced the exact Claude Code setup he now uses to ship more code than at any point in his career, part-time, while running YC. Where ECC keeps Claude disciplined, GStack gives it a whole team. It turns one agent into a virtual startup: a CEO that pushes back on your idea before you build the wrong thing, an engineering manager that plans the architecture, a designer that catches ugly AI output, a reviewer that hunts production bugs, a QA lead that opens a real browser and clicks through your app, and a release engineer that ships it. You drive it like a CEO, checking the big decisions and letting the rest run. For solo builders and small teams who want the rigor of a real engineering org without hiring one. If you&#39;re shipping actual products, not just experimenting, this is the workflow. Install by opening Claude Code and running:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>git clone --single-branch --depth 1 https://github.com/garrytan/gstack.git ~/.claude/skills/gstack &amp;&amp; cd ~/.claude/skills/gstack &amp;&amp; ./setup</span></span></code></pre></div><p>Then you run your work through a sprint, one command at a time. Here are a few of the commands you&#39;ll reach for most (there are 23 in total)</p><blockquote><p>/office-hours asks you six sharp questions to kill bad ideas early. /plan-eng-review designs the architecture before any code. /review scans what Claude wrote for real production bugs and fixes them. /qa opens an actual browser and tests your app like a user would, then writes regression tests so the bug never comes back. /ship runs the release with a full test audit. Each step feeds the next, so you go from idea to shipped without the usual mess.</p></blockquote><h1 id="_3-matt-pocock-skills-—-mattpocock-skills" tabindex="-1">3. Matt Pocock skills — mattpocock/skills <a class="header-anchor" href="#_3-matt-pocock-skills-—-mattpocock-skills" aria-label="Permalink to &quot;3. Matt Pocock skills — mattpocock/skills&quot;">​</a></h1><p>145,000+ stars Matt Pocock is a well-known TypeScript educator (he built Total TypeScript and teaches ~60,000 devs through his newsletter). He took the exact skills he uses every day for real engineering and published them. The repo crossed 145,000 stars almost entirely by word of mouth, developer telling developer, which tells you it hit a real nerve. His whole pitch is in the tagline: &quot;skills for real engineers, not vibe coding.&quot; Where GStack gives Claude a team, these skills give it discipline. They don&#39;t make the model smarter, they make it less reckless. The big one is that Claude loves to build the wrong thing because it assumed what you meant. His skills force it to stop guessing, ask sharp questions first, write tests properly, and keep your code from rotting into an unmaintainable mess as the agent moves fast. For anyone who&#39;s graduated from &quot;make me a quick app&quot; to actually maintaining real software, especially in TypeScript and JavaScript. If you&#39;ve watched Claude confidently build something you didn&#39;t ask for, this is the cure. Install by opening Claude Code and running:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>npx skills@latest add mattpocock/skills</span></span></code></pre></div><p>Pick the skills you want when prompted, and make sure you include /setup-matt-pocock-skills, which configures everything for your project. Then you call them when you need them. A few of the most useful (there are around 17):</p><blockquote><p>/grill-me interrogates you about what you actually want before a single line gets written, so you don&#39;t end up with the wrong feature. /tdd forces proper test-first development instead of Claude claiming code works without checking. /improve-codebase-architecture rescues a messy project that&#39;s become hard to change, and Matt recommends running it every few days to stop the rot. /diagnosing-bugs runs a disciplined debugging loop instead of random guessing. One note: these lean toward TypeScript and JavaScript conventions. If you work in a very different stack, you&#39;ll still get value, but some skills will fit better than others.</p></blockquote><h1 id="_4-graphify-—-safishamsi-graphify" tabindex="-1">4. Graphify — safishamsi/graphify <a class="header-anchor" href="#_4-graphify-—-safishamsi-graphify" aria-label="Permalink to &quot;4. Graphify — safishamsi/graphify&quot;">​</a></h1><p>70,000+ stars Remember the problem from earlier: Claude Code forgets everything between sessions and re-reads your whole project every time to figure out what&#39;s going on. On a mid-size codebase that burns tens of thousands of tokens before you&#39;ve even asked a question. Every session. That&#39;s slow and it&#39;s expensive. graphify fixes exactly that. It turns any folder, code, docs, even PDFs and images, into a queryable knowledge graph: a structured map of how everything connects. Instead of re-reading every file, Claude just queries the map and gets the answer. On the project&#39;s own benchmark that meant roughly 1,700 tokens per query instead of 123,000, about a 71x cut. It built one of the fastest-growing repos of the year, going viral 48 hours after Andrej Karpathy (OpenAI co-founder) posted his own knowledge-base workflow. (If you saw our breakdown of Karpathy&#39;s second-brain setup, this is the tool that does the heavy lifting.) For anyone working on a real codebase who&#39;s tired of slow, pricey sessions, or who wants Claude to actually understand how their project fits together instead of guessing file by file. Install by running this in your terminal first:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>uv tool install graphifyy</span></span></code></pre></div><p>(Yeah, with two y&#39;s, that&#39;s the official one). Then register it with your agent:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>graphify install</span></span></code></pre></div><p>Then in Claude Code, run /graphify . once to build the map of your project. First run is slower, after that it just updates what changed. From then on, ask normally:</p><blockquote><p>/graphify query &quot;how does login work?&quot; and Claude answers from the graph instead of reading every file. /graphify --update refreshes it when your docs change. You can even commit the map to git so your whole team&#39;s Claude starts already knowing the codebase. Note: the 71x figure is a best case on a specific project. Your savings depend on how big your codebase is. On small projects, plain Claude with search is sometimes just as cheap. Where graphify really pays off is on large, complex codebases run many times a day.</p></blockquote><h1 id="_5-gbrain-—-garrytan-gbrain" tabindex="-1">5. GBrain — garrytan/gbrain <a class="header-anchor" href="#_5-gbrain-—-garrytan-gbrain" aria-label="Permalink to &quot;5. GBrain — garrytan/gbrain&quot;">​</a></h1><p>24,000+ stars This is the second one from Garry Tan, the YC CEO, and it&#39;s the deep version of the memory problem. Where graphify gives Claude a memory of your code, GBrain gives it a memory of your whole working life: people, companies, meetings, emails, decisions, ideas. It&#39;s not a side project either. It&#39;s the actual production brain Garry runs his business on, holding 146,000+ pages, 24,000+ people, and 5,000+ companies, with dozens of automated jobs updating it while he sleeps. The magic is that it doesn&#39;t just hand you matching pages, it synthesizes an answer. Ask &quot;what do I need to know before my meeting with Alice tomorrow?&quot; and instead of ten links, you get written prose: what she works on, when you last spoke, what&#39;s still open between you, all cited. It builds a self-wiring graph of who knows whom and who did what, so it surfaces connections plain search would miss. For founders, investors, operators, and anyone whose work runs on relationships and context, not just code. If you&#39;ve ever walked into a meeting blanking on someone you&#39;ve emailed 50 times, this is built for exactly that. Wire it into Claude Code as a memory layer. The fastest way to try it is the local version, no accounts, no server, ready in about 30 seconds. In your terminal:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>git clone https://github.com/garrytan/gbrain.git &amp;&amp; cd gbrain</span></span>
<span class="line"><span>bun install &amp;&amp; bun link</span></span>
<span class="line"><span>gbrain init</span></span></code></pre></div><p>That sets up a local brain on your machine. Now feed it some notes and ask it something:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gbrain import ~/notes/</span></span>
<span class="line"><span>gbrain query &quot;what themes show up across my notes?&quot;</span></span></code></pre></div><p>To plug it into Claude Code so your agent can use it directly, run:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>claude mcp add gbrain -- gbrain serve</span></span></code></pre></div><p>From there you just talk to it in plain English. Point it at a folder of notes, meeting transcripts, or emails, then ask &quot;who works at Acme AI?&quot; or &quot;what did Bob invest in this quarter?&quot; and it answers from everything it&#39;s ingested, with citations. Later, you can connect Gmail, Google Calendar, and meeting transcripts so it keeps filling itself in automatically. One real heads up: that local version above is the easy on-ramp. The full system Garry runs, the one with auto-updating jobs and a team brain, means setting up a real database (Supabase), more API keys, and background jobs, plus real monthly cost if you go all in. Garry himself jokes in the docs that the full setup is &quot;too complicated for a normal person.&quot; So start local, get a feel for it, and only graduate to the full stack if you fall in love. Two install gotchas the project itself flags: don&#39;t use bun install -g github:garrytan/gbrain and don&#39;t use npm install -g gbrain (a fake package is squatting that name). Use the git clone path above.</p><h1 id="_6-skillspector-—-nvidia-skillspector" tabindex="-1">6. SkillSpector — NVIDIA/SkillSpector <a class="header-anchor" href="#_6-skillspector-—-nvidia-skillspector" aria-label="Permalink to &quot;6. SkillSpector — NVIDIA/SkillSpector&quot;">​</a></h1><p>5,500+ stars Every skill you add to Claude Code runs with real access to your files, your network, and your environment variables, and there&#39;s basically no security gate between &quot;install&quot; and &quot;it&#39;s running on your machine.&quot; A study of 42,447 real-world skills found that 26% of them contained a vulnerability and 5% showed likely malicious intent. That&#39;s not a rounding error. SkillSpector, built and open-sourced by NVIDIA, is the bouncer at the door. Point it at any skill before you install it and it scans for the dangerous stuff: hidden instructions, prompt injection, data exfiltration, sketchy code, and skills that quietly ask for way more access than they need. You get a 0-to-100 safety score and a clear &quot;should I install this or not.&quot; For literally everyone installing skills, which after this thread is you. Especially worth it before you add anything from a random GitHub repo or marketplace you don&#39;t recognize. Install it by opening Claude Code and just asking:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Install SkillSpector from https://github.com/NVIDIA/skillspector and use it to scan this skill before I add it</span></span></code></pre></div><p>Claude runs it for you. Under the hood it&#39;s a command-line tool, but you don&#39;t need to touch the terminal yourself, Claude Code handles the commands. Then any time you&#39;re about to add a new skill, have Claude scan it first. Point it at a GitHub repo, a folder, or a single file, and it hands back a risk report in seconds: a 0-to-100 score, what it found, and whether to trust it. Make this a habit, scan first, install second. It&#39;s the cheapest insurance on this whole list, and the one most people skip until something goes wrong. If you&#39;d rather run it yourself in the terminal, the manual command is:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>uv tool install git+https://github.com/NVIDIA/skillspector.git</span></span>
<span class="line"><span>skillspector scan https://github.com/some-author/some-skill</span></span></code></pre></div><h1 id="_7-cybersecurity-skills-—-mukul975-anthropic-cybersecurity-skills" tabindex="-1">7. Cybersecurity Skills — mukul975/Anthropic-Cybersecurity-Skills <a class="header-anchor" href="#_7-cybersecurity-skills-—-mukul975-anthropic-cybersecurity-skills" aria-label="Permalink to &quot;7. Cybersecurity Skills — mukul975/Anthropic-Cybersecurity-Skills&quot;">​</a></h1><p>4,000+ stars Staying on security, but flipping it around. The last one checked if skills are safe. This one makes Claude itself a security expert. It&#39;s a library of 817 structured cybersecurity skills, everything from malware analysis and threat hunting to cloud breaches and incident response, each one a step-by-step playbook mapped to the real frameworks the industry uses (MITRE ATT&amp;CK, NIST, and more). The idea is simple: a junior security analyst knows which tool to run on a suspicious file, which rules catch a specific attack, how to scope a breach across cloud providers. Your AI agent doesn&#39;t, until you give it these skills. Once installed, you can point Claude at a security problem and it stops guessing and starts following expert procedure. For developers who want to harden their own apps, security hobbyists, and anyone curious about defense. You don&#39;t need to be a security pro, the skills carry the expertise, you just point Claude at the problem. Install by opening Claude Code and running:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>npx skills add mukul975/Anthropic-Cybersecurity-Skills</span></span></code></pre></div><p>Then ask Claude security questions in plain English and it pulls the right playbook. &quot;Review my web app for the OWASP Top 10 vulnerabilities&quot; makes it audit your code against the standard list of common holes. &quot;Walk me through investigating this suspicious login activity&quot; gives you a real incident-response procedure instead of vague advice. Tip: don&#39;t load all 817 at once, install the domain you actually need (like cloud security or code scanning) so you don&#39;t bloat Claude&#39;s context.</p><h1 id="_8-openmontage-—-calesthio-openmontage" tabindex="-1">8. OpenMontage — calesthio/OpenMontage <a class="header-anchor" href="#_8-openmontage-—-calesthio-openmontage" aria-label="Permalink to &quot;8. OpenMontage — calesthio/OpenMontage&quot;">​</a></h1><p>18,000+ stars Time to step outside of code, because Claude Code isn&#39;t only for software. OpenMontage turns your AI agent into a full video production studio. You describe the video you want in plain language, and the agent does the whole thing: researches the topic, writes the script, generates or finds the visuals, adds narration and music, edits the timeline, and renders a finished MP4. It hit #1 on GitHub trending recently for good reason. Depending on the mode, that&#39;s either AI-generated clips (if you plug in models like Veo or Runway), real archival footage stitched into a timeline, or generated images animated into a polished edit. It has 12 different production pipelines: cinematic trailers, animated explainers, talking-head spokesperson videos, real-footage documentaries (pulling actual clips from open archives like NASA and Archive org), and more. You can even hand it a YouTube video you love and say &quot;make me something like this but about my topic,&quot; and it builds a plan from the reference. For creators, marketers, educators, and anyone who wants video without learning an editor or paying for five separate AI subscriptions. By the project&#39;s own examples, a 60-second narrated animated short can cost just over a dollar in API credits, and there&#39;s a fully free path using local models and free stock footage. Before installing, you&#39;ll need a few things on your machine: Python 3.10+, Node.js 18+, and FFmpeg (the video tool). Then open Claude Code and run:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>git clone https://github.com/calesthio/OpenMontage.git</span></span>
<span class="line"><span>cd OpenMontage</span></span>
<span class="line"><span>make setup</span></span></code></pre></div><p>Once it&#39;s set up, open the project in Claude Code and describe what you want in plain language:</p><blockquote><p>Make a 60-second animated explainer about how neural networks learn Or for the real-footage documentary path: Make a 75-second documentary montage about city life in the rain. Use real footage only, no narration. The agent researches your topic, writes and narrates the script, finds royalty-free music, burns in subtitles, and renders the final video. It shows you a plan and a cost estimate before spending anything, and runs its own quality checks before handing you the finished cut. You can also paste a YouTube or TikTok link and say &quot;make one like this but about my topic.&quot; Heads up: the free path gives you a polished animated video (think moving visuals with narration and captions), not Hollywood-grade filmed footage. For AI-generated motion clips you&#39;ll need to plug in paid models. Either way, this is the most resource-heavy one to set up, so start with a short 30-to-60-second clip to get a feel for it before attempting anything big.</p></blockquote><h1 id="_9-deerflow-—-bytedance-deer-flow" tabindex="-1">9. DeerFlow — bytedance/deer-flow <a class="header-anchor" href="#_9-deerflow-—-bytedance-deer-flow" aria-label="Permalink to &quot;9. DeerFlow — bytedance/deer-flow&quot;">​</a></h1><p>74,000+ stars This one&#39;s from ByteDance, the company behind TikTok, and it&#39;s the heaviest hitter on this list. DeerFlow is built for the long, complex tasks that would normally take you hours or days. You hand it something big like &quot;research the top 10 AI startups of 2026 and build me a presentation,&quot; and instead of choking on it, a lead agent breaks the job into pieces, spins up a team of sub-agents to work in parallel (one scrapes data, another does analysis, another builds charts), and stitches it all back together at the end. The difference from a normal chatbot is that it actually does the work in a real, sandboxed environment, it doesn&#39;t just describe what it would do. It runs code, builds files, generates dashboards and slide decks, and produces finished deliverables. It has its own memory, its own filesystem, and it can run for a long time without losing the thread. When it launched, it shot to #1 on GitHub trending in 24 hours. For people with genuinely big, multi-step jobs: deep research reports, data pipelines, building dashboards, automating whole content workflows. This is overkill for &quot;write me a function,&quot; it shines when the task is large enough that you&#39;d want to delegate it and walk away. Install by opening Claude Code and running:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>git clone https://github.com/bytedance/deer-flow.git</span></span>
<span class="line"><span>cd deer-flow</span></span>
<span class="line"><span>make setup</span></span></code></pre></div><p>That launches a setup wizard for your API keys and preferences. Then start it (Docker is the recommended way):</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>make docker-start</span></span></code></pre></div><p>It opens a full agent interface in your browser. You can even connect it to Telegram or Slack and fire off tasks from your phone. Two honest notes. First, it&#39;s model-agnostic (works with Claude, GPT, Gemini, and others), but it&#39;s the most infrastructure-heavy setup here, it really wants Docker and some real machine resources, so it&#39;s aimed at more technical users. Second, since it&#39;s a ByteDance project that runs code and fetches data, some people and companies will want to review the security and country-of-origin context before deploying it for serious work. The code is open (MIT) and auditable, just go in informed.</p><h1 id="_10-openclaw-—-openclaw-openclaw" tabindex="-1">10. OpenClaw — openclaw/openclaw <a class="header-anchor" href="#_10-openclaw-—-openclaw-openclaw" aria-label="Permalink to &quot;10. OpenClaw — openclaw/openclaw&quot;">​</a></h1><p>250,000+ stars Saving the biggest for last. OpenClaw is the fastest-growing open-source project in GitHub history. An Austrian developer named Peter Steinberger built the first version in about an hour as a personal experiment, and within months it blew past React to become the most-starred piece of actual software on all of GitHub. OpenAI hired him off the back of it. Everything else on this list lives inside your coding tool. OpenClaw breaks the AI agent out of the terminal and puts it in the apps you already use: WhatsApp, Telegram, Slack, Discord, iMessage, and dozens more. It runs locally on your own machine, around the clock, so you can text your AI assistant from your phone like a friend and it actually does things: manages your calendar, handles email, runs research, controls tools, all on your own devices with your own data. This is the &quot;where it&#39;s all heading&quot; pick: not a coding helper, but a personal agent that lives in your life. For people who want a true 24/7 personal assistant they fully own and control, not a cloud service that logs everything you type. If you&#39;ve ever wished you could just message an AI to handle stuff while you&#39;re away from your computer, this is that. Install it in your terminal:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>npm install -g openclaw@latest</span></span>
<span class="line"><span>openclaw onboard --install-daemon</span></span></code></pre></div><p>The onboard wizard walks you through connecting your messaging apps and your AI model (bring your own Claude or OpenAI key). Once it&#39;s running, you just message it on whatever app you connected, &quot;summarize my unread emails and draft replies,&quot; &quot;remind me to call the dentist at 3pm,&quot; and it works in the background.</p><h1 id="the-bottom-line" tabindex="-1">The Bottom Line <a class="header-anchor" href="#the-bottom-line" aria-label="Permalink to &quot;The Bottom Line&quot;">​</a></h1><p>That&#39;s the 10. Quick recap before you go install everything at once: don&#39;t. Start with one. If you write code, ECC is the obvious first move, it fixes the most pain for the least effort. If your problem is Claude forgetting things, go graphify. If you just want to see something cool, OpenMontage makes a video in minutes. Pick the one that matches your actual problem, install it, use it for a week. Then come back for the next. And whatever you add, scan it first with SkillSpector. Popularity isn&#39;t safety. If this was useful, head to my profile and follow. I write about AI, Claude, and systems that actually run.</p><h2 id="ciao" tabindex="-1">Ciao, <a class="header-anchor" href="#ciao" aria-label="Permalink to &quot;Ciao,&quot;">​</a></h2><h2 id="undefinedki" tabindex="-1">@undefinedKi <a class="header-anchor" href="#undefinedki" aria-label="Permalink to &quot;@undefinedKi&quot;">​</a></h2><hr><h2 id="研究摘要" tabindex="-1">研究摘要 <a class="header-anchor" href="#研究摘要" aria-label="Permalink to &quot;研究摘要&quot;">​</a></h2><p><strong>TL;DR</strong>：2026 年 Claude Code 生態系 10 個高星數 open-source repo 導覽（ECC/GStack/Matt Pocock/Graphify/GBrain/SkillSpector/Cybersec Skills/OpenMontage/DeerFlow/OpenClaw），每個附安裝指令與使用情境，並批評多數社群推薦為噪音。</p><h3 id="核心論點" tabindex="-1">核心論點 <a class="header-anchor" href="#核心論點" aria-label="Permalink to &quot;核心論點&quot;">​</a></h3><ul><li><strong>ECC（affaan-m/ECC, 210k+ stars）</strong>：規則強制 + 記憶持久化，防 Claude 亂做承諾；指令：<code>/plugin marketplace add https://github.com/affaan-m/ECC</code></li><li><strong>GStack（garrytan/gstack, 115k stars）</strong>：Garry Tan（YC CEO）的虛擬團隊框架（23 個指令：/office-hours→/plan-eng-review→/review→/qa→/ship）</li><li><strong>Graphify（safishamsi/graphify, 70k stars）</strong>：codebase 知識圖，benchmark 宣稱 71x token reduction（1,700 vs 123,000 tokens/query）；安裝 <code>uv tool install graphifyy</code>（兩個 y）</li><li><strong>GBrain（garrytan/gbrain, 24k stars）</strong>：個人/組織 memory layer（146k 頁、24k 人、5k 公司），MCP 接入 Claude Code；local 版 30 秒啟動，完整版需 Supabase</li><li><strong>SkillSpector（NVIDIA/SkillSpector, 5.5k stars）</strong>：skill 安裝前安全掃描，0-100 評分；研究引用 42,447 個 skill 中 26% 含漏洞、5% 疑惡意</li><li><strong>DeerFlow（bytedance/deer-flow, 74k stars）</strong>：ByteDance 多 agent 平行執行框架，model-agnostic，需 Docker；ByteDance 出品需審視安全上下文</li><li><strong>OpenClaw（openclaw/openclaw, 250k stars）</strong>：最高星數，跨 WhatsApp/Telegram/iMessage 等通訊 app 運行本地 AI agent</li></ul><h3 id="關鍵數據-工具" tabindex="-1">關鍵數據 / 工具 <a class="header-anchor" href="#關鍵數據-工具" aria-label="Permalink to &quot;關鍵數據 / 工具&quot;">​</a></h3><ul><li>Graphify 71x token reduction（1,700 → 123,000 tokens/query，自家 benchmark）</li><li>SkillSpector 引用數據：26% skills 含漏洞，5% 疑似惡意（42,447 個 skill 研究）</li><li>GBrain 警告：<code>npm install -g gbrain</code> 為假包（squat），使用 git clone 路徑</li><li>安裝優先順序建議：ECC（寫程式者）→ Graphify（記憶問題）→ OpenMontage（視覺展示）</li></ul><h3 id="批判性觀察" tabindex="-1">批判性觀察 <a class="header-anchor" href="#批判性觀察" aria-label="Permalink to &quot;批判性觀察&quot;">​</a></h3><ul><li><strong>數據可信度存疑</strong>：ECC 210k、OpenClaw 250k、Matt Pocock 145k stars — 部分宣稱難以驗證（「GitHub 史上最快成長」等為行銷語言）</li><li><strong>SkillSpector 數據</strong>：26%/5% 引用來源未標注，但 NVIDIA 背書提升可信度</li><li><strong>Graphify 71x 警示</strong>：文章自注「best case on a specific project」，實際收益因 codebase 大小而異</li><li><strong>DeerFlow ByteDance 安全疑慮</strong>：作者誠實標注 country-of-origin context，是此類導覽少見的坦誠</li><li><strong>內容結構為推廣向</strong>：每個 repo 均附 follow CTA，可能與部分 repo 有利益關係</li></ul><hr><h2 id="評分" tabindex="-1">評分 <a class="header-anchor" href="#評分" aria-label="Permalink to &quot;評分&quot;">​</a></h2><table tabindex="0"><thead><tr><th>維度</th><th>分數</th><th>說明</th></tr></thead><tbody><tr><td>A. Workspace 可行動性 (30%)</td><td>7/10</td><td>SkillSpector（skill 安全掃描流程）+ Graphify（71x token 替代方案）對 workspace 直接相關；GBrain 補充 MEMORY.md 以外的記憶模式</td></tr><tr><td>B. 創新性 (20%)</td><td>5/10</td><td>清單彙整格式；SkillSpector 安全掃描角度新穎，其餘模式（多 agent/記憶/規則）已知</td></tr><tr><td>C. 證據品質 (20%)</td><td>5/10</td><td>星數難以獨立驗證；Graphify 71x 為自家 benchmark；26%/5% 引用來源未標注</td></tr><tr><td>D. 技術深度 (15%)</td><td>6/10</td><td>每個 repo 附具體安裝指令 + 使用情境；DeerFlow/Graphify 有誠實的限制說明</td></tr><tr><td>E. 泛化性 (15%)</td><td>7/10</td><td>提供 Claude Code 生態系全面地圖，對任何 Claude Code 使用者均有參考價值</td></tr><tr><td><strong>加權總分</strong></td><td><strong>6.05/10</strong></td><td>7×0.3+5×0.2+5×0.2+6×0.15+7×0.15</td></tr></tbody></table><p><strong>整合決策</strong>：Agent <strong>理由</strong>：SkillSpector（NVIDIA skill 安全掃描）是 workspace 目前缺少的具體安全流程；Graphify 的 knowledge graph 替代 raw file scan 的方向值得追蹤驗證；需進一步確認 repo 真實性後決定是否整合。</p>`,79)])])}const g=t(n,[["render",i]]);export{p as __pageData,g as default};
